begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values
('ca000000-0000-4000-8000-000000000001','community-retry-a@mizyun.test'),
('ca000000-0000-4000-8000-000000000002','community-retry-b@mizyun.test'),
('ca000000-0000-4000-8000-000000000003','community-retry-c@mizyun.test');
update public.profiles set birth_year=1990 where id::text like 'ca000000-%';
insert into public.workouts(id,user_id,name,started_at,completed_at,details)
values('da000000-0000-4000-8000-000000000001','ca000000-0000-4000-8000-000000000001','Private source',now()-interval '1 hour',now(),'{"workoutLifecycle":{"kind":"session"}}');
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='ca000000-0000-4000-8000-000000000001';
select is((select available from public.community_handle_available('retry_author')),true,'Unclaimed handle reports available before enrollment');
select is_empty($$select * from public.community_get_profile(auth.uid())$$,'Never-enrolled self lookup is empty rather than null row');
select * from public.community_save_profile('retry_author','Author','AU','Author bio',false,true,'2026-09-30');
select * from public.community_create_invitation('AbCdEf0123456789_-AbCd',7);
set local request.jwt.claim.sub='ca000000-0000-4000-8000-000000000002';
select is((select available from public.community_handle_available('retry_author')),false,'Hidden handle reservation exposes boolean only');
select * from public.community_save_profile('retry_follower','Follower','FO','Follower bio',false,true,'2026-09-30');
select throws_ok($$select * from public.community_request_follow('ca000000-0000-4000-8000-000000000001',null,'e1430000-0000-4000-8000-000000000101')$$,'P0001','community_unavailable','Guessed hidden identity is not a follow capability');
select lives_ok($$select * from public.community_request_follow('ca000000-0000-4000-8000-000000000001','AbCdEf0123456789_-AbCd','e1430000-0000-4000-8000-000000000102')$$,'Valid token can request hidden author');
select is((select count(*) from public.community_relationships),1::bigint,'Follow retry returns original edge');
select * from public.community_request_follow('ca000000-0000-4000-8000-000000000001','AbCdEf0123456789_-AbCd','e1430000-0000-4000-8000-000000000103');
select is((select count(*) from public.community_relationships),1::bigint,'Repeated follow has no duplicate edge');
update public.community_relationships set status='canceled' where follower_user_id=auth.uid();
delete from public.community_relationships where follower_user_id=auth.uid();
select is((select count(*) from public.community_relationships),1::bigint,'Raw delete cannot erase canceled request cooldown');
select throws_ok($$select * from public.community_request_follow('ca000000-0000-4000-8000-000000000001','AbCdEf0123456789_-AbCd','e1430000-0000-4000-8000-000000000104')$$,'P0001','community_rate_limited','Cancel/delete/retry cannot bypass cooldown');
reset role;
set local request.jwt.claim.role='service_role';
update public.community_relationships set status='pending' where follower_user_id='ca000000-0000-4000-8000-000000000002';
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='ca000000-0000-4000-8000-000000000001';
update public.community_relationships set status='approved' where target_user_id=auth.uid();
select is((select count(*) from public.community_get_profile('ca000000-0000-4000-8000-000000000002')),1::bigint,'Author can manage hidden approved follower');
select is((select bio from public.community_get_profile('ca000000-0000-4000-8000-000000000002')),null,'Reverse approved edge does not reveal follower bio');
select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,3600,1,'aa000000-0000-4000-8000-000000000001');
select is((select version from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,3600,1,'aa000000-0000-4000-8000-000000000001')),1,'Lost publication response retries stable version');
select throws_ok($$select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','running',(now() at time zone 'UTC')::date::text,3600,1,'aa000000-0000-4000-8000-000000000001')$$,'P0001','community_conflict','Operation UUID cannot be reused with changed payload');
set local request.jwt.claim.sub='ca000000-0000-4000-8000-000000000002';
insert into public.community_reactions(activity_id,user_id,reaction) select id,auth.uid(),'clap' from public.community_feed(20,null,null);
set local request.jwt.claim.sub='ca000000-0000-4000-8000-000000000001';
select * from public.community_update_activity((select id from public.shared_activities),null);
select is((select version from public.shared_activities),2,'Duration edit advances snapshot version');
reset role;
set local request.jwt.claim.role='service_role';
select is((select count(*) from public.community_reactions where user_id='ca000000-0000-4000-8000-000000000002'),0::bigint,'Duration edit invalidates all follower reactions');
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='ca000000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,3600,1,'aa000000-0000-4000-8000-000000000001')$$,'P0001','community_conflict','Old operation cannot replay after snapshot edit');
update public.shared_activities set revoked_at=now() where user_id=auth.uid();
select throws_ok($$update public.shared_activities set revoked_at=null where user_id=auth.uid()$$,'42501',null,'Raw owner update cannot resurrect revoked publication');
select throws_ok($$select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,3600,1,'aa000000-0000-4000-8000-000000000001')$$,'P0001','community_conflict','Revoked operation remains rejected');
select lives_ok($$select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'aa000000-0000-4000-8000-000000000002',2,true)$$,'New explicit operation may republish revoked source');
select community_withdraw_profile();
select * from public.community_save_profile('retry_author','Author','AU',null,false,true,'2026-09-30');
select is((select generation from public.community_get_profile(auth.uid())),2,'Explicit reenrollment advances generation');
select throws_ok($$select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,1,'aa000000-0000-4000-8000-000000000003')$$,'P0001','community_conflict','Old generation confirmation fails');
select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,2,'aa000000-0000-4000-8000-000000000003',3,true);
delete from public.workouts where id='da000000-0000-4000-8000-000000000001';
reset role;
set local request.jwt.claim.role='service_role';
insert into public.workouts(id,user_id,name,started_at,completed_at,details)
values('da000000-0000-4000-8000-000000000001','ca000000-0000-4000-8000-000000000001','Recreated private source',now()-interval '1 hour',now(),'{"workoutLifecycle":{"kind":"session"}}');
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='ca000000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_publish_activity('da000000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text,null,2,'aa000000-0000-4000-8000-000000000003',3,true)$$,'P0001','community_conflict','Deleted source retains operation tombstone even if UUID recreated');
select throws_ok($$insert into public.community_reports(reporter_user_id,target_type,target_id,reason,status) values(auth.uid(),'profile','ca000000-0000-4000-8000-000000000002','spam','resolved')$$,'42501',null,'Reporter cannot forge moderator status');
update public.profiles set birth_year=extract(year from now())::integer - 17 where id=auth.uid();
select is((select status from public.community_get_profile(auth.uid())),'withdrawn','Loss of adult eligibility withdraws social state');
select * from finish();
rollback;
